const r = await tools.exec_command({cmd:"python3 - <<'PY'
from pathlib import Path
import numpy as np
from pynwb import NWBHDF5IO
pre=post=rewarded_bins=rewarded_trials=omitted_trials=excluded=0
examples=[]
for path in sorted(Path('/app/data').glob('sub-*/*.nwb')):
 with NWBHDF5IO(str(path),'r',load_namespaces=True) as io:
  nwb=io.read(); b=nwb.processing['behavior']['BehavioralTimeSeries']; n=len(b['position'].data); ts=np.asarray(b['position'].timestamps[:n]); start=np.flatnonzero(np.asarray(b['trial_start'].data[:n])>0); stop=np.flatnonzero(np.asarray(b['teleport'].data[:n])>0); lick=np.asarray(b['lick'].data[:n]); rewards=np.asarray(b['Reward'].timestamps[:])
  for ti,(a,e) in enumerate(zip(start,stop)):
   if np.mean(lick[a:e]>2)>.30: excluded+=1; continue
   inside=rewards[(rewards>=ts[a])&(rewards<ts[e])]
   if len(inside):
    rewarded_trials+=1; rewarded_bins+=e-a; cut=np.searchsorted(ts[a:e],inside[0],side='left'); pre+=cut; post+=(e-a-cut)
    if len(examples)<2: examples.append((path.name,ti,'rewarded',round(float(inside[0]-ts[a]),3),e-a))
   else:
    omitted_trials+=1
    if len(examples)==2: examples.append((path.name,ti,'omitted',None,e-a))
print(f'outcome_raw_audit retained_rewarded={rewarded_trials} retained_omitted={omitted_trials} excluded={excluded}')
print(f'rewarded_trial_bins={rewarded_bins} pre_first_delivery={pre} ({pre/rewarded_bins:.3%}) post_delivery={post} ({post/rewarded_bins:.3%})')
print('specific_raw_examples=',examples)
PY","workdir":"/app","yield_time_ms":30000,"max_output_tokens":10000}); text(r.output); if(r.session_id) text(`SESSION_ID=${r.session_id}`);

